// porte un marqueur <!--slot:nom--> à l'endroit de l'ancienne image.
const LIGHT = '#E8F1F3';
const OK = '#2E9D6B';
const KO = '#F26B6B';
const card = 'background:' + LIGHT + ';border-radius:var(--osd-radius);box-shadow:rgba(0,82,103,.12) 0 6px 16px;box-sizing:border-box;';

// Slide « Permis ou interdit ? » : liste complète, à droite des deux encarts de synthèse.
const item = (ok: boolean, text: string) =>
  `<li style="display:flex;gap:14px;align-items:baseline"><span style="color:${ok ? OK : KO};font-weight:700;flex-shrink:0">${ok ? '✓' : '✗'}</span><span>${text}</span></li>`;
const list = (title: string, ok: boolean, items: string[]) =>
  `<div style="font-family:var(--osd-font-display);font-size:28px;font-weight:700;margin:0 0 12px">${title}</div>` +
  `<ul style="list-style:none;margin:0 0 26px;padding:0;display:flex;flex-direction:column;gap:7px">${items.map((t) => item(ok, t)).join('')}</ul>`;
const TYPES_VOL = `<div style="position:absolute;right:100px;top:180px;width:640px;height:790px;padding:30px 36px;font-size:20px;line-height:1.3;${card}">
${list('Possible', true, [
  'Vol depuis un véhicule en mouvement',
  'Vol près des personnes (selon la sous-catégorie)',
  'FPV avec un observateur, le pilote reste responsable',
  'Vol en zone ségréguée, sur accord du gestionnaire',
  'Mode « follow me » : 50 m max en A1/A3',
  'Vol automatisé en A2',
  'Vol de nuit, sur dérogation',
  'Tout type de capteur (caméra thermique, lidar…)',
  'Pas de MANEX obligatoire ni de surveillance DSAC',
])}
${list('Interdit', false, [
  'Drone de plus de 250 g sans marquage C0, C1 ou C2 à moins de 150 m des habitations, zones de loisirs et industrielles',
  "Survol de l'espace public en agglomération, sauf vol professionnel",
  'Vol hors vue, vol en essaim',
  'Épandage, largage : rien ne doit tomber du drone',
  'Transport de marchandises dangereuses ou de personnes',
  'Survol de rassemblements de personnes',
])}</div>`;

// Slide « La synthèse » : tableau par classe de drone (C0 à C4).
const yes = `<span style="color:${OK};font-weight:700">✓</span>`;
const no = `<span style="color:${KO};font-weight:700">✗</span>`;
const td = (html: string, span = 1) =>
  `<td colspan="${span}" style="border:2px solid #FFFFFF;background:${LIGHT};padding:8px 10px;text-align:center">${html}</td>`;
const row = (label: string, cells: string) =>
  `<tr><th style="border:2px solid #FFFFFF;background:#005267;color:#FFFFFF;padding:8px 12px;text-align:left;font-weight:600;width:210px">${label}</th>${cells}</tr>`;
const head = (c: string, sub: string) =>
  `<th style="border:2px solid #FFFFFF;background:#08B8DC;color:#003E50;padding:8px 6px;font-size:24px">${c}<div style="font-size:17px;font-weight:600">${sub}</div></th>`;
const SYNTHESE = `<div style="position:absolute;left:100px;top:270px;width:1000px">
<table style="width:100%;border-collapse:collapse;font-size:19px;line-height:1.25;table-layout:fixed">
<tr><th style="width:210px"></th>${head('C0', 'A1')}${head('C1', 'A1')}${head('C2', 'A2')}${head('C3', 'A3')}${head('C4', 'A3')}</tr>
${row('Masse max', td('&lt; 250 g') + td('&lt; 900 g') + td('&lt; 4 kg') + td('&lt; 25 kg') + td('&lt; 25 kg'))}
${row('Formation', td('Notice<br>(CCIO : A1/A3)') + td('A1/A3') + td('A1/A3<br>+ BAPD') + td('A1/A3') + td('A1/A3'))}
${row('Enregistrement exploitant', td(yes) + td(yes) + td(yes) + td(yes) + td(yes))}
${row('Identification à distance', td(no) + td('Remote ID') + td('Remote ID') + td('Remote ID') + td('FR si ≥ 800 g'))}
${row('Hauteur max', td('120 m (+ 15 m au-dessus d’un obstacle artificiel)', 5))}
${row('Survol de tiers', td('Toléré, pas de rassemblement') + td('Toléré si involontaire') + td('Non : 30 m<br>(5 m en basse vitesse)') + td('Non : 150 m des zones habitées', 2))}
${row('Vitesse max', td('19 m/s') + td('19 m/s') + td('Mode basse vitesse 3 m/s') + td('Pas de limite', 2))}
${row('Géovigilance', td(no) + td(yes) + td(yes) + td(yes) + td(no))}
</table>
<div style="font-size:20px;font-style:italic;margin-top:18px">On peut toujours voler dans une sous-catégorie plus contraignante : l'A3 est ouverte à toutes les classes.</div></div>`;

