const AXES = `<svg viewBox="0 0 880 320" style="display:block;width:100%;height:320px" role="img" aria-label="Les trois axes du drone : tangage, roulis, lacet">
<defs>${ARROW}</defs>${panel(0, 'Tangage', 'pitch', SIDE)}${panel(293, 'Roulis', 'roll', FRONT)}${panel(586, 'Lacet', 'yaw', TOP)}</svg>`;

// Cas pratique « Le drone perso » : petit drone de loisir, sans numéro d'exploitant CCIO.
const DRONE_PERSO = `<svg viewBox="0 0 760 620" style="position:absolute;left:100px;top:270px;width:760px;height:620px" role="img" aria-label="Petit drone personnel de moins de 250 g, sans étiquette d'exploitant CCIO">
<rect width="760" height="620" rx="16" fill="${LIGHT}"/>
<g transform="translate(380 270) scale(1.9)">${TOP.split('<path')[0]}</g>
<g transform="translate(560 90) rotate(8)"><rect x="-80" y="-36" width="160" height="72" rx="14" fill="#FFDE12"/>
<text y="14" text-anchor="middle" font-family="JetBrains Mono, Consolas, monospace" font-size="38" font-weight="700" fill="#003E50">249 g</text></g>
<g transform="translate(380 530)"><rect x="-200" y="-40" width="400" height="80" rx="12" fill="#FFFFFF" stroke="${KO}" stroke-width="4" stroke-dasharray="14 10"/>
<text y="13" text-anchor="middle" font-family="JetBrains Mono, Consolas, monospace" font-size="34" font-weight="700" fill="${KO}">FRA- ? ? ? ?</text></g></svg>`;

// Slide « Lire la carte OACI » : extrait Géoportail (SCAN OACI IGN) flouté, la licence IGN
// excluant la reproduction graphique. Les repères sont redessinés par-dessus, aux bons endroits.
const pin = (x: number, y: number, code: string, name: string) =>
  `<div style="position:absolute;left:${x}px;top:${y}px;transform:translate(-14px,-14px);display:flex;align-items:center;gap:10px">` +
  `<span style="width:28px;height:28px;border-radius:50%;background:#08B8DC;border:5px solid #003E50;box-sizing:border-box;flex-shrink:0"></span>` +
  `<span style="background:#003E50;color:#FFFFFF;border-radius:10px;padding:6px 12px;font-size:22px;line-height:1.2;white-space:nowrap">` +
  `<b style="font-family:JetBrains Mono,Consolas,monospace;color:#FFDE12">${code}</b> ${name}</span></div>`;
const tag = (x: number, y: number, text: string, color: string, dashed = false) =>
  `<div style="position:absolute;left:${x}px;top:${y}px;background:rgba(255,255,255,.92);color:${color};border:3px ${dashed ? 'dashed' : 'solid'} ${color};border-radius:10px;padding:5px 12px;font-family:JetBrains Mono,Consolas,monospace;font-size:21px;font-weight:700;white-space:nowrap">${text}</div>`;
const OACI = `<div style="position:absolute;left:100px;top:270px;width:1030px;height:666px;border-radius:var(--osd-radius);overflow:hidden">
<img alt="Carte OACI floutée autour d'Oléron et Rochefort, avec les repères principaux" src="assets/oaci.jpg" style="display:block;width:100%;height:100%;object-fit:cover">
${pin(202, 268, 'LFDP', 'Saint-Pierre-d’Oléron')}
${pin(563, 569, 'LFJI', 'Marennes')}
${pin(711, 424, 'LFDN', 'Rochefort')}
${tag(560, 300, 'RMZ Rochefort', '#003E50', true)}
${tag(760, 150, 'Zones R / D / P', '#D64545')}
<div style="position:absolute;left:16px;bottom:12px;font-size:17px;font-style:italic;color:#FFFFFF;text-shadow:0 1px 3px rgba(0,0,0,.6)">Fond flouté : carte OACI-VFR, à consulter sur Géoportail</div></div>`;

const SLOTS: Record<string, string> = { 'types-vol': TYPES_VOL, synthese: SYNTHESE, axes: AXES, 'drone-perso': DRONE_PERSO, oaci: OACI };
const withSlots = (html: string) => html.replace(/<!--slot:([\w-]+)-->/g, (_, s: string) => SLOTS[s]);

// ---------------------------------------------------------------- numéro de page
// L'export avait des numéros figés : on les retire et on les recalcule, pour pouvoir supprimer
// ou déplacer des pages. Seules les pages qui en avaient un en affichent un.
const NUM_RE = /<div style="position: absolute; bottom: 40px; right: 100px; font-size: 22px; font-weight: 700;">\d+<\/div>/;
const PageNum = () => {
  const { current } = useSlidePageNumber();
  return <div style={{ position: 'absolute', bottom: 40, right: 100, fontSize: 22, fontWeight: 700 }}>{current}</div>;
};

// Contenu statique écrit par le SIT (aucune saisie utilisateur) : l'injection HTML est sans risque.
const toPage = (html: string): Page => {
  const numbered = NUM_RE.test(html);
  const markup = { __html: withAssets(withSlots(html.replace(NUM_RE, ''))) };
  return () => (
    <div style={{ width: '100%', height: '100%', position: 'relative' }}>
      <div style={{ width: '100%', height: '100%' }} dangerouslySetInnerHTML={markup} />
      {numbered && <PageNum />}
    </div>
  );
};

export const meta: SlideMeta = {
  title: 'GT Drone CCIO · Réglementation & pilotage - 13 octobre 2026',
  createdAt: '2026-11-04T15:10:45.422Z',
};

export default HTML.map(toPage) satisfies Page[];
